import{_ as t,a0 as s,w as c,s as r,ao as n,I as d,x as i,a1 as o,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"使用 Vi/Vim 编辑器：基础篇 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Vi/Vim 编辑器：基础篇 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Vi/Vim 编辑器：基础篇 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Vi/Vim 编辑器：基础篇 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20170511 Working with VI editor - The Basics","title":"使用 Vi/Vim 编辑器：基础篇","tag":"201802","desc":""},"relativePath":"201802/20170511 Working with VI editor - The Basics.md","filePath":"[post].md"}'),p={name:"201802/20170511 Working with VI editor - The Basics.md"};function h(m,e,V,b,f,u){const l=s("Link");return c(),r("div",null,[e[8]||(e[8]=n('<h1 id="使用-vi-vim-编辑器-基础篇" tabindex="-1">使用 Vi/Vim 编辑器：基础篇 <a class="header-anchor" href="#使用-vi-vim-编辑器-基础篇" aria-label="Permalink to “使用 Vi/Vim 编辑器：基础篇”">​</a></h1><p>VI 编辑器是一个基于命令行的、功能强大的文本编辑器，最早为 Unix 系统开发，后来也被移植到许多的 Unix 和 Linux 发行版上。</p><p>在 Linux 上还存在着另一个 VI 编辑器的高阶版本 —— VIM（也被称作 VI IMproved）。VIM 只是在 VI 已经很强的功能上添加了更多的功能，这些功能有：</p><ul><li>支持更多 Linux 发行版，</li><li>支持多种编程语言，包括 python、c++、perl 等语言的代码块折叠，语法高亮，</li><li>支持通过多种网络协议，包括 http、ssh 等编辑文件，</li><li>支持编辑压缩归档中的文件，</li><li>支持分屏同时编辑多个文件。</li></ul><p>接下来我们会讨论 VI/VIM 的命令以及选项。本文出于教学的目的，我们使用 VI 来举例，但所有的命令都可以被用于 VIM。首先我们先介绍 VI 编辑器的两种模式。</p><h3 id="命令模式" tabindex="-1">命令模式 <a class="header-anchor" href="#命令模式" aria-label="Permalink to “命令模式”">​</a></h3><p>命令模式下，我们可以执行保存文件、在 VI 内运行命令、复制/剪切/粘贴操作，以及查找/替换等任务。当我们处于插入模式时，我们可以按下 <code>Escape</code>（<code>Esc</code>）键返回命令模式</p><h3 id="插入模式" tabindex="-1">插入模式 <a class="header-anchor" href="#插入模式" aria-label="Permalink to “插入模式”">​</a></h3><p>在插入模式下，我们可以键入文件内容。在命令模式下按下 <code>i</code> 进入插入模式。</p><h3 id="创建文件" tabindex="-1">创建文件 <a class="header-anchor" href="#创建文件" aria-label="Permalink to “创建文件”">​</a></h3><p>我们可以通过下述命令建立一个文件（LCTT 译注：如果该文件存在，则编辑已有文件）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi filename</span></span></code></pre></div><p>一旦该文件被创建或者打开，我们首先进入命令模式，我们需要进入输入模式以在文件中输入内容。我们通过前文已经大致上了解这两种模式。</p><h3 id="退出-vi" tabindex="-1">退出 Vi <a class="header-anchor" href="#退出-vi" aria-label="Permalink to “退出 Vi”">​</a></h3><p>如果是想从插入模式中退出，我们首先需要按下 <code>Esc</code> 键进入命令模式。接下来我们可以根据不同的需要分别使用两种命令退出 Vi。</p><ol><li>不保存退出 - 在命令模式中输入 <code>:q!</code></li><li>保存并退出 - 在命令模式中输入 <code>:wq</code></li></ol><h3 id="移动光标" tabindex="-1">移动光标 <a class="header-anchor" href="#移动光标" aria-label="Permalink to “移动光标”">​</a></h3><p>下面我们来讨论下那些在命令模式中移动光标的命令和选项：</p><ol><li><p><code>k</code> 将光标上移一行</p></li><li><p><code>j</code> 将光标下移一行</p></li><li><p><code>h</code> 将光标左移一个字母</p></li><li><p><code>l</code> 将光标右移一个字母</p><p>注意：如果你想通过一个命令上移或下移多行，或者左移、右移多个字母，你可以使用 <code>4k</code> 或者 <code>5l</code>，这两条命令会分别上移 4 行或者右移 5 个字母。</p></li><li><p><code>0</code> 将光标移动到该行行首</p></li><li><p><code>$</code> 将光标移动到该行行尾</p></li><li><p><code>nG</code> 将光标移动到第 n 行</p></li><li><p><code>G</code> 将光标移动到文件的最后一行</p></li><li><p><code>{</code> 将光标移动到上一段</p></li><li><p><code>}</code> 将光标移动到下一段</p></li></ol><p>除此之外还有一些命令可以用于控制光标的移动，但上述列出的这些命令应该就能应付日常工作所需。</p><h3 id="编辑文本" tabindex="-1">编辑文本 <a class="header-anchor" href="#编辑文本" aria-label="Permalink to “编辑文本”">​</a></h3><p>这部分会列出一些用于命令模式的命令，可以进入插入模式来编辑当前文件</p><ol><li><code>i</code> 在当前光标位置之前插入内容</li><li><code>I</code> 在光标所在行的行首插入内容</li><li><code>a</code> 在当前光标位置之后插入内容</li><li><code>A</code> 在光标所在行的行尾插入内容</li><li><code>o</code> 在当前光标所在行之后添加一行</li><li><code>O</code> 在当前光标所在行之前添加一行</li></ol><h3 id="删除文本" tabindex="-1">删除文本 <a class="header-anchor" href="#删除文本" aria-label="Permalink to “删除文本”">​</a></h3><p>以下的这些命令都只能在命令模式下使用，所以首先需要按下 <code>Esc</code> 进入命令模式，如果你正处于插入模式：</p><ol><li><code>dd</code> 删除光标所在的整行内容，可以在 <code>dd</code> 前增加数字，比如 <code>2dd</code> 可以删除从光标所在行开始的两行</li><li><code>d$</code> 删除从光标所在位置直到行尾</li><li><code>d^</code> 删除从光标所在位置直到行首</li><li><code>dw</code> 删除从光标所在位置直到下一个词开始的所有内容</li></ol><h3 id="复制与黏贴" tabindex="-1">复制与黏贴 <a class="header-anchor" href="#复制与黏贴" aria-label="Permalink to “复制与黏贴”">​</a></h3><ol><li><code>yy</code> 复制当前行，在 <code>yy</code> 前添加数字可以复制多行</li><li><code>p</code> 在光标之后粘贴复制行</li><li><code>P</code> 在光标之前粘贴复制行</li></ol><p>上述就是可以在 VI/VIM 编辑器上使用的一些基本命令。在未来的教程中还会继续教授一些更高级的命令。如果有任何疑问和建议，请在下方评论区留言。</p><hr>',30)),d("p",null,[e[1]||(e[1]=i("via: ",-1)),o(l,{href:"http://linuxtechlab.com/working-vi-editor-basics/"},{default:a(()=>[...e[0]||(e[0]=[i("http://linuxtechlab.com/working-vi-editor-basics/",-1)])]),_:1})]),d("p",null,[e[5]||(e[5]=i("作者：",-1)),o(l,{href:"http://linuxtechlab.com/author/shsuain/"},{default:a(()=>[...e[2]||(e[2]=[i("Shusain",-1)])]),_:1}),e[6]||(e[6]=i(" 译者：",-1)),o(l,{href:"https://github.com/ljgibbslf"},{default:a(()=>[...e[3]||(e[3]=[i("ljgibbslf",-1)])]),_:1}),e[7]||(e[7]=i(" 校对：",-1)),o(l,{href:"https://github.com/wxy"},{default:a(()=>[...e[4]||(e[4]=[i("wxy",-1)])]),_:1})]),e[9]||(e[9]=d("p",null,"本文由 LCTT 原创编译，Linux中国 荣誉推出",-1))])}const g=t(p,[["render",h]]);export{T as __pageData,g as default};
